import {comparisonNotes,windowReview,aiContext} from './evidence.mjs';
import {connectionFrom,requestAI} from './ai.mjs';
import {CHANNELS,DEFAULTS,STATUS,validateParams,validateRecord,parseOutput,diagnose,ruleExplanation} from './core.mjs';
const $=id=>document.getElementById(id),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const fmt=(v,d=1)=>Number.isFinite(v)?v.toLocaleString('zh-CN',{minimumFractionDigits:d,maximumFractionDigits:d}):'—';
const COLORS=['#4e8de5','#58b9bf','#a18ad0','#e2ad66'];
const STORAGE='tideflow-workspace-v1';
let runs=[],selected=null,comparison=new Set(),local=false,token=null,active=null,channel='GenPwr',topic='summary',ai=null,aiAbort=null,engineeringAbort=null,pollTimer=null,toastTimer=null,imported=[],draft={...DEFAULTS},polling=false,knowledge=[];
function current(){return runs.find(r=>r.id===selected)||null;}
function toast(text,error=false){clearTimeout(toastTimer);$('toast').textContent=text;$('toast').className='toast'+(error?' error':'');$('toast').hidden=false;toastTimer=setTimeout(()=>$('toast').hidden=true,6000);}
function download(name,content,type='application/json'){const url=URL.createObjectURL(new Blob([content],{type})),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),2000);}
function cancelAI(){if(aiAbort){aiAbort.abort();aiAbort=null;}engineeringAbort?.abort();}
function persist(){try{localStorage.setItem(STORAGE,JSON.stringify({selected,comparison:[...comparison],draft,imported}));}catch{toast('浏览器存储空间不足，请导出工作区备份。',true);}}
function labelSource(r){return r.source_kind==='imported-unverified'?'用户导入 · 待核验':r.source_kind==='bundled-openfast'?'内置真实算例':'本机 OpenFAST';}
function waveLabel(p){return p.wave_mode==='regular'?'规则波':'JONSWAP';}
function fillForm(p){draft={...p};for(const [key,id] of Object.entries({name:'case-name',wind:'wind',wave_height:'wave-height',wave_period:'wave-period',wave_mode:'wave-mode',duration:'duration',discard:'discard',seed:'seed',solver_dt:'solver-dt'}))$(id).value=p[key];updateDraft();}
function readForm(){return {name:$('case-name').value,wind:Number($('wind').value),wave_height:Number($('wave-height').value),wave_period:Number($('wave-period').value),wave_mode:$('wave-mode').value,duration:Number($('duration').value),discard:Number($('discard').value),seed:Number($('seed').value),solver_dt:Number($('solver-dt').value)};}
function updateDraft(){draft=readForm();$('wind-value').textContent=fmt(draft.wind,1);$('wave-height-label').textContent=draft.wave_mode==='regular'?'波高 H / m':'显著波高 Hs / m';$('wave-period-label').textContent=draft.wave_mode==='regular'?'周期 T / s':'峰值周期 Tp / s';const r=current();$('draft-note').hidden=!r||JSON.stringify(draft)===JSON.stringify(r.params);persist();}
async function api(path,body){const response=await fetch(path,{method:body?'POST':'GET',headers:body?{'Content-Type':'application/json','X-Run-Token':token}:{},body:body?JSON.stringify(body):undefined});let data;try{data=await response.json();}catch{throw Error('本机服务未返回有效 JSON。');}if(!response.ok){if(data.login_required)window.dispatchEvent(new Event('tideflow:login-required'));throw Error(data.error||'请求失败：'+response.status);}return data;}
function plots(){const r=current();if(!r?.result)return [];const chosen=runs.filter(x=>comparison.has(x.id)&&x.status==='completed'&&x.id!==r.id);return [r,...chosen].slice(0,4);}
function selectRun(id,{form=true}={}){if(!runs.some(r=>r.id===id))return;selected=id;const r=current();if(comparison.size&&r.status==='completed'&&!comparison.has(id)){if(comparison.size>=4)comparison.delete(comparison.values().next().value);comparison.add(id);}if(form)fillForm(r.params);render();persist();}
function chartSVG(records,key,{width=760,height=240}={}){
 const valid=records.filter(r=>r.result?.channels.includes(key));if(!valid.length)return '<div class="empty">该工况尚无完整有效的时序结果。</div>';
 const left=62,right=19,top=20,bottom=height-35,w=width-left-right,h=bottom-top;let ymin=Infinity,ymax=-Infinity,xmax=0;
 for(const r of valid){const i=r.result.channels.indexOf(key);for(const row of r.result.series){ymin=Math.min(ymin,row[i]);ymax=Math.max(ymax,row[i]);xmax=Math.max(xmax,row[0]);}}
 const padding=Math.max((ymax-ymin)*.12,Math.abs(ymax)*.02,.01);ymin-=padding;ymax+=padding;if(key==='GenPwr')ymin=Math.min(0,ymin);
 const x=v=>left+v/Math.max(xmax,1)*w,y=v=>bottom-(v-ymin)/(ymax-ymin)*h;
 let svg=`<svg viewBox="0 0 ${width} ${height}" role="img" aria-label="${esc(CHANNELS[key].label)}时间响应图">`;
 const r=current();if(r?.result)svg+=`<rect x="${x(r.result.analysis_start)}" y="${top}" width="${Math.max(0,x(r.result.analysis_end)-x(r.result.analysis_start))}" height="${h}" fill="#edf5fe"/>`;
 for(let i=0;i<=4;i++){const v=ymin+(ymax-ymin)*i/4,yy=y(v);svg+=`<path d="M${left} ${yy}H${width-right}" stroke="#e7edf3" stroke-dasharray="3 4"/><text x="${left-10}" y="${yy+3}" text-anchor="end" fill="#a6b3bf" font-size="9">${fmt(v,Math.abs(v)<10?1:0)}</text>`;}
 for(let i=0;i<=4;i++){const t=xmax*i/4;svg+=`<text x="${x(t)}" y="${height-13}" text-anchor="middle" fill="#a6b3bf" font-size="9">${fmt(t,0)} s</text>`;}
 valid.forEach((record,j)=>{const i=record.result.channels.indexOf(key),series=record.result.series,stride=Math.max(1,Math.ceil(series.length/1800)),points=[];for(let k=0;k<series.length;k+=stride)points.push(series[k]);if(points.at(-1)!==series.at(-1))points.push(series.at(-1));const d=points.map((row,k)=>`${k?'L':'M'}${x(row[0]).toFixed(2)},${y(row[i]).toFixed(2)}`).join(' ');svg+=`<path d="${d}" fill="none" stroke="${COLORS[j%4]}" stroke-width="1.7" stroke-linejoin="round"><title>${esc(record.name)}</title></path>`;});
 return svg+'</svg>';
}
function renderChart(){const r=current(),records=plots();$('time-chart').innerHTML=chartSVG(records,channel);$('chart-unit').textContent=`${channel} / ${CHANNELS[channel].unit}`;$('chart-window').textContent=r?.result?`完整时序 · 统计窗口 ${r.result.analysis_start}—${r.result.analysis_end} s · ${records.length} 个工况叠加`:'完整时序 · 等待有效结果';$('chart-legend').innerHTML=records.map((r,i)=>`<button data-plot-run="${esc(r.id)}" style="display:flex;align-items:center;gap:5px;padding:0;background:none;color:inherit;font-size:inherit"><i style="background:${COLORS[i%4]}"></i>${esc(r.name)}</button>`).join('');document.querySelectorAll('[data-channel]').forEach(b=>{b.classList.toggle('active',b.dataset.channel===channel);b.setAttribute('aria-pressed',String(b.dataset.channel===channel));b.disabled=!records.some(x=>x.result?.channels.includes(b.dataset.channel));});window.dispatchEvent(new CustomEvent('tideflow:chart',{detail:{record:r,records,channel}}));}
function renderHistory(){const ordered=[...runs].sort((a,b)=>String(b.created).localeCompare(String(a.created)));$('run-count').textContent=runs.length;
 $('history-table').innerHTML=ordered.length?`<table><thead><tr><th>对比</th><th>工况</th><th>风速 / m/s</th><th>波浪 / 波高 / 周期</th><th>分析窗口 / s</th><th>状态</th><th>来源</th><th>查看</th></tr></thead><tbody>${ordered.map(r=>`<tr><td><input class="compare-check" type="checkbox" aria-label="对比 ${esc(r.name)}" data-compare="${esc(r.id)}" ${comparison.has(r.id)?'checked':''} ${r.status!=='completed'?'disabled':''}></td><td><strong>${esc(r.name)}</strong><br><small>${esc(r.id.slice(0,12))} · ${r.elapsed_seconds?fmt(r.elapsed_seconds,1)+' s 计算':''}</small></td><td>${r.params.wind}</td><td>${waveLabel(r.params)} / ${r.params.wave_height} m / ${r.params.wave_period} s</td><td>${r.params.discard}—${r.params.duration}</td><td><span class="badge ${r.status}">${STATUS[r.status]}</span></td><td><small>${labelSource(r)}</small></td><td><button class="table-button ${r.id===selected?'active':''}" data-view="${esc(r.id)}">${r.id===selected?'当前':'查看'}</button></td></tr>`).join('')}</tbody></table>`:'<div class="empty">暂无运行记录。启动本机引擎提交工况，或导入已有输出。</div>';
}
function renderComparison(){const records=runs.filter(r=>comparison.has(r.id)&&r.status==='completed');if(!records.length){$('comparison-table').innerHTML='<div class="empty">在运行记录中勾选工况后，统计与曲线将同步对比。</div>';$('comparison-note').textContent='勾选最多 4 个已完成工况。建议一次只改变一个变量。';return;}
 $('comparison-note').textContent=comparisonNotes(records).join(' ');
 $('comparison-table').innerHTML=`<table><thead><tr><th>工况</th><th>平均功率 / kW</th><th>平均转速 / rpm</th><th>纵摇绝对峰值 / °</th><th>纵荡绝对峰值 / m</th><th>窗口发电量 / kWh</th></tr></thead><tbody>${records.map(r=>`<tr><td><strong>${esc(r.name)}</strong></td><td>${fmt(r.result.stats.GenPwr.mean)}</td><td>${fmt(r.result.stats.RotSpeed.mean,2)}</td><td>${fmt(r.result.stats.PtfmPitch.max_abs,3)}</td><td>${fmt(r.result.stats.PtfmSurge.max_abs,3)}</td><td>${fmt(r.result.energy_kwh,2)}</td></tr>`).join('')}</tbody></table>`;
}
function findingsHTML(findings,{completed=false}={}){return findings.length?findings.map(f=>`<article class="finding ${f.severity}"><h3>${f.severity==='error'?'!':'△'} ${esc(f.title)}</h3><p>${esc(f.advice)}</p><pre>${esc(f.evidence)}</pre><a href="${esc(f.source)}" target="_blank" rel="noopener">OpenFAST 排查文档 ↗</a></article>`).join(''):`<div class="no-findings"><strong>${completed?'当前规则未匹配到常见异常':'当前没有可定位的报错'}</strong>${completed?'仍需检查原始日志和模型适用性。规则未命中不代表工程结果已经有效。':'保留包含报错前后调用链的原始日志，避免只截取最后一行。'}</div>`;}
function renderSources(){const r=current(),p=r?.provenance;$('provenance-details').innerHTML=`<div class="source-row"><span>参考模型</span><div>NREL 5 MW / OC4-DeepCwind 半潜式平台<br>水深 200 m；官方初始条件；OC3Hywind 控制器<br><a href="https://github.com/OpenFAST/r-test/tree/dd5feaaaa500ba7283140107806300d551cff0a7/glue-codes/openfast/5MW_OC4Semi_WSt_WavesWN" target="_blank" rel="noopener">官方算例与固定版本 ↗</a></div></div><div class="source-row"><span>引擎版本</span><div>OpenFAST v5.0.0 / Windows double precision<br><a href="https://github.com/OpenFAST/openfast/releases/tag/v5.0.0" target="_blank" rel="noopener">官方发行版 ↗</a><br>程序 SHA-256：${esc(p?.engine_sha256||'本记录未提供，需核验')}</div></div><div class="source-row"><span>算例版本</span><div>${esc(p?.rtest_sha||'导入结果未提供')}<br>所选记录来源：${esc(r?labelSource(r):'无')}</div></div><div class="source-row"><span>输入校验</span><div>${r?.input_sha256?Object.entries(r.input_sha256).map(([file,sha])=>`${esc(file)}<br><code>${esc(sha)}</code>`).join('<br>'):'导入记录未提供已核验输入。'}</div></div><div class="source-row"><span>输出与统计</span><div>输出间隔 0.1 s；严格验证时间递增、通道和单位。分析窗口采用梯形积分，计算时间加权均值、RMS、标准差及窗口发电量。<br>输出 SHA-256：${esc(r?.result?.output_sha256||'未提供')}</div></div><div class="source-row"><span>原始文件</span><div>${local&&r?.artifacts?`<a href="${esc(r.artifacts.output)}" download>下载完整 .out 输出</a> · <a href="${esc(r.artifacts.log)}" download>下载完整运行日志</a><br>`:''}<a href="./MODEL-LICENSE.txt" target="_blank" rel="noopener">参考模型 Apache-2.0 许可</a> · <a href="https://openfast.readthedocs.io/" target="_blank" rel="noopener">OpenFAST 文档</a></div></div>`;}
function render(){cancelAI();const r=current();$('result-title').textContent=r?.name||'选择或提交一个工况';$('result-subtitle').textContent=r?`${labelSource(r)} · ${r.params.wind} m/s · ${waveLabel(r.params)} ${r.params.wave_height} m / ${r.params.wave_period} s`:'从官方算例开始，保留计算证据';$('result-status').className='badge '+(r?.status||'');$('result-status').textContent=r?STATUS[r.status]:'等待数据';
 const stats=r?.result?.stats;$('metric-power').textContent=fmt(stats?.GenPwr.mean,0);$('metric-speed').textContent=fmt(stats?.RotSpeed.mean,2);$('metric-pitch').textContent=fmt(stats?.PtfmPitch.max_abs,2);$('insight-text').textContent=ruleExplanation(r,topic);
 $('engine-log').textContent=r?.logs?.length?r.logs.join('\n'):r?.error||'该记录未提供日志。可在右侧粘贴其他日志进行排查。';$('log-line-count').textContent=`${r?.logs?.length||0} 行（最多展示 1200 行）`;$('diagnosis-list').innerHTML=findingsHTML(r?.findings||[],{completed:r?.status==='completed'});
 const a=runs.find(x=>x.id===active);$('active-progress').hidden=!a;if(a){$('progress-label').textContent=`${a.name} · ${STATUS[a.status]}`;if(a.progress>0)$('run-progress').value=a.progress;else $('run-progress').removeAttribute('value');$('progress-detail').textContent=a.progress>0?`引擎日志报告进度 ${fmt(a.progress,1)}% · ${a.params.duration} s 仿真；实际耗时取决于本机算力`:'引擎初始化或运行中，尚未收到新的时间进度。';}
 $('run-button').disabled=!!active;$('run-button').innerHTML=active?'<span>◌</span> 仿真进行中':`<span>▶</span> ${local?'提交真实仿真':'在本机运行新工况'} <b>↗</b>`;
 renderChart();renderHistory();renderComparison();renderSources();renderReview();if(r)showReferences(aiContext(r,topic,knowledge).references);updateDraft();publishAnalysis();}
function publishAnalysis(){window.dispatchEvent(new CustomEvent('tideflow:render',{detail:{record:current(),count:runs.length,records:runs,compared:[...comparison],plots:plots(),channel}}));}
window.addEventListener('tideflow:analysis-request',()=>{publishAnalysis();renderChart();});
window.addEventListener('tideflow:analysis-action',event=>{const {type,id}=event.detail||{};if(type==='select')selectRun(id,{form:false});if(type==='compare'){const candidate=runs.find(r=>r.id===id&&r.status==='completed');if(!candidate)return;if(comparison.has(id))comparison.delete(id);else{const base=current();const ids=new Set(base?.result?[base.id,...comparison]:comparison);if(ids.size>=4&&!ids.has(id))return toast('最多同时比较 4 个工况。',true);if(base?.result)comparison.add(base.id);comparison.add(id);}render();persist();}if(type==='clear'){comparison.clear();render();persist();}});
async function loadLocalRuns(){if(!local)return;const data=await api('/api/runs');const merged=new Map(runs.map(r=>[r.id,r]));for(const r of data.runs)merged.set(r.id,validateRecord(r));runs=[...merged.values()];}
async function poll(){if(!local||!active||polling)return;polling=true;try{const record=validateRecord(await api('/api/runs/'+active)),i=runs.findIndex(r=>r.id===record.id);if(i>=0)runs[i]=record;else runs.push(record);if(!['running','preparing'].includes(record.status)){active=null;toast(record.status==='completed'?'仿真完成，已校验输出并生成分析统计。':record.error||'运行已取消。',record.status==='failed');}render();}catch(error){toast('本机服务连接中断：'+error.message,true);}finally{polling=false;if(active)pollTimer=setTimeout(poll,2000);}}
function reportHTML(){const r=current();if(!r?.result)throw Error('请选择已完成的有效工况。');let records=plots();if(!records.some(x=>x.id===r.id))records=[r,...records].slice(0,4);
 return `<article class="report-body"><div class="stamp">TIDEFLOW / OFFSHORE WIND / OPENFAST 5.0.0</div><h1>海上风电多工况仿真分析报告</h1><p>生成时间：${esc(new Date().toLocaleString('zh-CN'))}。参考模型：NREL 5 MW / OC4-DeepCwind 半潜式平台，水深 200 m。工况均为人工设置。</p><h2>1. 工况与来源</h2><table><thead><tr><th>工况</th><th>风速 m/s</th><th>波浪模式</th><th>波高参数 m</th><th>周期参数 s</th><th>种子</th><th>窗口 s</th><th>来源</th></tr></thead><tbody>${records.map(x=>`<tr><td>${esc(x.name)}</td><td>${x.params.wind}</td><td>${waveLabel(x.params)}</td><td>${x.params.wave_height}</td><td>${x.params.wave_period}</td><td>${x.params.seed}</td><td>${x.result.analysis_start}—${x.result.analysis_end}</td><td>${labelSource(x)}</td></tr>`).join('')}</tbody></table><p>规则波的波高与周期分别为 H、T；不规则波为显著波高 Hs 和峰值周期 Tp。固定官方初始条件，风向及波向均为基准值。求解步长：${records.map(x=>`${esc(x.name)} ${x.params.solver_dt} s`).join("；")}。</p><h2>2. 分析窗口统计</h2><table><thead><tr><th>工况</th><th>平均功率 kW</th><th>平均转速 rpm</th><th>纵摇绝对峰值 °</th><th>纵荡绝对峰值 m</th><th>窗口发电 kWh</th></tr></thead><tbody>${records.map(x=>`<tr><td>${esc(x.name)}</td><td>${fmt(x.result.stats.GenPwr.mean)}</td><td>${fmt(x.result.stats.RotSpeed.mean,2)}</td><td>${fmt(x.result.stats.PtfmPitch.max_abs,3)}</td><td>${fmt(x.result.stats.PtfmSurge.max_abs,3)}</td><td>${fmt(x.result.energy_kwh,2)}</td></tr>`).join('')}</tbody></table><p>时间加权均值与能量采用梯形积分；kW × s / 3600 = kWh。统计计算使用全部输出样本，图形显示可能抽点。</p><h2>3. 发电功率时序</h2><div class="report-chart">${chartSVG(records,'GenPwr')}</div><h2>4. 平台纵摇时序</h2><div class="report-chart">${chartSVG(records,'PtfmPitch')}</div><p>${records.map((x,i)=>`曲线 ${i+1}：${esc(x.name)}`).join('；')}。浅蓝区域标注当前选中工况的分析窗口。</p><h2>5. 当前工况解释</h2><p>${esc(ruleExplanation(r,'summary')).replace(/\n/g,'<br>')}</p><h2>6. 运行证据与日志提示</h2>${records.map(x=>`<p><b>${esc(x.name)}</b>：ID ${esc(x.id)}；状态 ${STATUS[x.status]}；耗时 ${fmt(x.elapsed_seconds)} s；输出 ${x.result.full_samples} 行。<br>原始输出 SHA-256：${esc(x.result.output_sha256||'未提供')}<br>引擎 SHA-256：${esc(x.provenance?.engine_sha256||'未提供')}<br>参考模型提交：${esc(x.provenance?.rtest_sha||'未提供')}<br>日志规则匹配：${x.findings.length?x.findings.map(f=>esc(f.title)).join('；'):'未匹配常见异常，仍需核查原始日志。'}</p>`).join('')}<h2>7. 对照与窗口检查</h2><p>${esc(comparisonNotes(records).join(" "))}</p>${records.map(x=>`<p><b>${esc(x.name)}</b>：${esc(windowReview(x).notes.join(" "))}<br>${windowReview(x).channels.map(c=>`${esc(c.name)} 前后半窗均值 ${fmt(c.first,3)} → ${fmt(c.second,3)}；相对变化 ${fmt(c.relative_shift*100,1)}%`).join("；")}</p>`).join("")}<h2>8. 判断边界</h2><ul><li>短时演示工况未证明充分稳态，也未开展疲劳、极限工况、模型校准或工程认证。</li><li>控制其他变量并统一分析窗口，才能合理解释工况差异；不规则波需要考虑随机种子和足够的统计时长。</li><li>不由单一短时序列外推全年发电量，不据此直接判定工程安全。</li><li>导入结果的参数与来源由用户声明，未经本工作台独立核验。原始文件和输入哈希请通过运行记录导出保留。</li></ul><p>来源：<a href="https://github.com/OpenFAST/openfast/releases/tag/v5.0.0">OpenFAST 官方程序</a>；<a href="https://github.com/OpenFAST/r-test">r-test 参考模型</a>；<a href="https://openfast.readthedocs.io/">官方文档</a>。</p></article>`;
}
function renderReview(){const r=current(),review=windowReview(r);$('quality-notes').textContent=review.notes.join(' ');$('quality-table').innerHTML=review.channels.length?`<table><thead><tr><th>通道</th><th>前半窗均值</th><th>后半窗均值</th><th>均值变化 / 较大 RMS</th></tr></thead><tbody>${review.channels.map(c=>`<tr><td>${CHANNELS[c.name].label} / ${CHANNELS[c.name].unit}</td><td>${fmt(c.first,3)}</td><td>${fmt(c.second,3)}</td><td>${fmt(c.relative_shift*100,1)}%</td></tr>`).join('')}</tbody></table>`:'';}
function showReferences(refs){$('ai-references').innerHTML=refs.map(e=>`<p><a href="${esc(e.url)}" target="_blank" rel="noopener">[${esc(e.id)}] ${esc(e.title)} ↗</a><br>${esc(e.summary)}</p>`).join('');}
window.addEventListener('tideflow:engineering-ask',async e=>{
 const {requestId,question,module}=e.detail||{};
 const reply=text=>window.dispatchEvent(new CustomEvent('tideflow:engineering-answer',{detail:{requestId,text}}));
 if(typeof question!=='string'||!question.trim()||question.length>600)return;
 engineeringAbort?.abort();
 if(!ai){reply('请先点击“连接 AI”填写接口、模型和密钥，连接后可继续发送这个问题。');return;}
 const controller=new AbortController();engineeringAbort=controller;
 const timer=setTimeout(()=>controller.abort(),45000);
 try{const text=await requestAI(ai,{question,context:{kind:'工程原理讨论',module,limits:['仅讨论给定模块原理；此处没有真实运行结果，不得编造数值或仿真结论。']},local,token,signal:controller.signal});reply(text);}
 catch(error){reply(controller.signal.aborted?'请求已取消或超时，请重试。':'AI 暂时无法回答：'+error.message);}
 finally{clearTimeout(timer);if(engineeringAbort===controller)engineeringAbort=null;}
});
async function askAI(q){const r=current();if(!r)return;const context=aiContext(r,q,knowledge,readForm());showReferences(context.references);if(!ai){$('insight-text').textContent=ruleExplanation(r,topic);toast('当前使用规则解释；下方提供相关文档依据。');return;}cancelAI();const controller=new AbortController();aiAbort=controller;const timer=setTimeout(()=>controller.abort(),45000);$('insight-text').textContent='正在结合工况证据与文档摘要请求模型…';
try{const text=await requestAI(ai,{question:q,context,local,token,signal:controller.signal});if(aiAbort===controller)$('insight-text').textContent=text+'\n\n模型生成解释，引用编号对应下方材料；仍需专业复核。';}catch(error){if(aiAbort===controller){$('insight-text').textContent=ruleExplanation(r,topic);toast((error.name==='AbortError'?'模型请求超时':error.message)+'；已恢复规则解释。',true);}}finally{clearTimeout(timer);if(aiAbort===controller)aiAbort=null;}}
document.querySelectorAll('.close').forEach(b=>b.onclick=()=>b.closest('dialog').close());document.querySelectorAll('dialog').forEach(d=>d.onclick=e=>{if(e.target===d){const r=d.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)d.close();}});
document.querySelectorAll('[data-scroll]').forEach(b=>b.onclick=()=>{document.querySelectorAll('[data-scroll]').forEach(x=>x.classList.toggle('active',x===b));$(b.dataset.scroll).scrollIntoView({behavior:'smooth',block:'start'});});
$('source-open').onclick=()=>$('source-dialog').showModal();['help-open','local-open'].forEach(id=>$(id).onclick=()=>$('help-dialog').showModal());$('model-open').onclick=()=>$('ai-dialog').showModal();
$('case-form').addEventListener('input',updateDraft);$('reset-config').onclick=()=>fillForm(DEFAULTS);
$('case-form').onsubmit=async e=>{e.preventDefault();if(!local){$('help-dialog').showModal();return;}try{const p=validateParams(readForm()),record=validateRecord(await api('/api/runs',p));runs.push(record);selected=record.id;active=record.id;render();clearTimeout(pollTimer);pollTimer=setTimeout(poll,1000);window.dispatchEvent(new CustomEvent('tideflow:navigate',{detail:'analysis'}));toast('已提交本机 OpenFAST，等待真实引擎输出。');}catch(error){toast(error.message,true);}};
$('cancel-run').onclick=async()=>{if(!active)return;try{await api('/api/runs/'+active+'/cancel',{});toast('已请求停止仿真，部分输出不作为完整结果。');}catch(error){toast(error.message,true);}};
$('history-table').onclick=e=>{const b=e.target.closest('[data-view]');if(b){selectRun(b.dataset.view);window.dispatchEvent(new CustomEvent('tideflow:navigate',{detail:'analysis'}));}};
$('history-table').onchange=e=>{const id=e.target.dataset.compare;if(!id)return;if(e.target.checked){if(comparison.size>=4){e.target.checked=false;return toast('最多同时比较 4 个工况。',true);}comparison.add(id);selected=id;fillForm(current().params);}else comparison.delete(id);render();persist();};
document.querySelectorAll('[data-channel]').forEach(b=>b.onclick=()=>{channel=b.dataset.channel;renderChart();});document.querySelectorAll('[data-topic]').forEach(b=>b.onclick=()=>{topic=b.dataset.topic;document.querySelectorAll('[data-topic]').forEach(x=>x.classList.toggle('active',x===b));if(ai)askAI({summary:'解释当前工况的性能结果',motion:'解释当前工况的平台运动',wave:'解释本工况的波浪参数与序列',limits:'解释这些结果可以支持什么判断，有什么局限'}[topic]);else {const r=current();$('insight-text').textContent=ruleExplanation(r,topic);if(r)showReferences(aiContext(r,b.textContent,knowledge).references);}});
$('chart-legend').onclick=e=>{const button=e.target.closest('[data-plot-run]');if(button)selectRun(button.dataset.plotRun);};
$('export-current').onclick=()=>{const r=current();if(!r)return toast('没有可导出的运行记录。',true);download('OpenFAST-运行记录-'+r.id.slice(0,8)+'.json',JSON.stringify({schema:1,run:r},null,2));};
$('export-project').onclick=()=>download('潮汐-仿真工作区.json',JSON.stringify({schema:1,runs,selected,comparison:[...comparison],draft},null,2));
$('export-csv').onclick=()=>{const r=current();if(!r?.result)return toast('请先选择有效的完成结果。',true);const x=r.result;download('OpenFAST-时序-'+r.id.slice(0,8)+'.csv','\ufeff'+x.channels.map((n,i)=>n+'_'+x.units[i]).join(',')+'\r\n'+x.series.map(row=>row.join(',')).join('\r\n'),'text/csv;charset=utf-8');};
$('download-log').onclick=()=>{const r=current();if(!r?.logs?.length)return toast('当前记录未提供运行日志。',true);if(local&&r.artifacts?.log){const a=document.createElement('a');a.href=r.artifacts.log;a.download='OpenFAST.log';a.click();}else download('OpenFAST-'+r.id.slice(0,8)+'.log',r.logs.join('\n'),'text/plain;charset=utf-8');};
$('import-run').onclick=()=>$('import-file').click();$('import-file').onchange=async e=>{try{const file=e.target.files[0];if(!file)return;if(file.size>12e6)throw Error('导入文件应小于 12 MB。');const text=await file.text();let added=[];if(/\.json$/i.test(file.name)){const data=JSON.parse(text);const records=data.run?[data.run]:Array.isArray(data.runs)?data.runs:[data];if(!records.length||records.length>50)throw Error('一次最多导入 50 条记录。');added=records.map(raw=>{const r=validateRecord(raw,{imported:true});r.id='import-'+crypto.randomUUID();return r;});}else{const params=validateParams(readForm()),result=parseOutput(text,params);added=[{id:'import-'+crypto.randomUUID(),name:file.name.slice(0,60),params,status:'completed',created:new Date().toISOString(),source_kind:'imported-unverified',logs:[],findings:[],result,engine_version:'用户文件未核验',case:'用户导入'}];}
 if(imported.length+added.length>50)throw Error('浏览器最多保留 50 条导入记录，请先导出备份。');imported.push(...added);runs.push(...added);selectRun(added[0].id);toast(`已导入 ${added.length} 条记录；参数及来源待核验。`);}catch(error){toast(error.message+'（导入 .out 时请先配置对应的仿真时长与分析起点。）',true);}finally{e.target.value='';}};
$('paste-log-open').onclick=()=>$('paste-dialog').showModal();$('analyze-log').onclick=()=>{const text=$('pasted-log').value.trim();if(!text)return toast('请先粘贴日志。',true);$('pasted-findings').innerHTML=findingsHTML(diagnose(text));};
$('report-open').onclick=()=>{try{$('report-preview').innerHTML=reportHTML();$('report-dialog').showModal();}catch(error){toast(error.message,true);}};
$('download-report').onclick=()=>{try{download('海上风电仿真分析报告.html',`<!doctype html><html lang="zh-CN"><meta charset="utf-8"><title>海上风电仿真分析报告</title><style>body{max-width:1100px;padding:30px;margin:auto;font:12px/1.9 sans-serif;color:#29465c}h1{font-size:25px}h2{font-size:17px;margin-top:24px}table{width:100%;border-collapse:collapse;font-size:10px}td,th{border:1px solid #d8e3eb;text-align:left;padding:9px}.stamp{color:#8ba0b1;font-size:9px}.report-chart svg{width:100%;height:auto}a{overflow-wrap:anywhere}@media print{body{padding:0}tr,.report-chart{break-inside:avoid}}</style>${reportHTML()}</html>`,'text/html;charset=utf-8');}catch(error){toast(error.message,true);}};
$('print-report').onclick=()=>{try{$('print-area').innerHTML=reportHTML();$('report-dialog').close();window.print();}catch(error){toast(error.message,true);}};
function readAI(){return connectionFrom({url:$('ai-url').value,model:$('ai-model').value,key:$('ai-key').value||ai?.key||''});}
$('ai-form').onsubmit=e=>{e.preventDefault();try{cancelAI();ai=readAI();$('ai-key').value='';$('ai-dialog').close();$('insight-mode').textContent='大模型讨论 · '+ai.model;$('ask-input').placeholder='输入问题，讨论当前工况…';toast('已保存连接；连接检测可验证服务，尚不代表解释质量已验证。');}catch(error){toast(error.message,true);}};
$('ai-test').onclick=async()=>{const button=$('ai-test'),controller=new AbortController(),timer=setTimeout(()=>controller.abort(),45000);try{const connection=readAI();button.disabled=true;$('ai-test-status').textContent='正在检测文本响应，不发送仿真数据…';await requestAI(connection,{probe:true,local,token,signal:controller.signal});$('ai-test-status').textContent='连接检测通过：服务返回有效文本。模型解释质量仍需实测。';}catch(error){$('ai-test-status').textContent=error.name==='AbortError'?'连接检测超时。':error.message;}finally{button.disabled=false;clearTimeout(timer);}};
$('ai-disconnect').onclick=()=>{cancelAI();ai=null;$('ai-key').value='';$('insight-mode').textContent='规则解释 · 可追溯';$('ask-input').placeholder='接入 AI 后，继续讨论当前工况…';$('ai-dialog').close();$('insight-text').textContent=ruleExplanation(current(),topic);toast('已清除内存中的密钥。');};$('ask-form').onsubmit=e=>{e.preventDefault();const q=$('ask-input').value.trim();if(q){askAI(q);$('ask-input').value='';}};
async function init(){try{let restored=null;try{const raw=localStorage.getItem(STORAGE);if(raw)restored=JSON.parse(raw);}catch{}const response=await fetch('./samples.json');if(!response.ok)throw Error('内置算例记录未加载，请检查 samples.json。');const data=await response.json();knowledge=(await fetch('./knowledge.json').then(r=>{if(!r.ok)throw Error('文档摘要加载失败');return r.json();})).entries;runs=data.runs.map(r=>validateRecord(r));if(restored){try{imported=(restored.imported||[]).slice(0,50).map(r=>validateRecord(r,{imported:true}));runs.push(...imported);selected=restored.selected;comparison=new Set((restored.comparison||[]).filter(id=>runs.some(r=>r.id===id&&r.status==='completed')).slice(0,4));draft=validateParams(restored.draft);}catch{imported=[];toast('部分本地记录无效，已载入官方示例。',true);}}
 if(['localhost','127.0.0.1'].includes(location.hostname)){try{const health=await fetch('/api/health').then(r=>r.json());if(health.service==='offshore-assistant'){local=true;token=health.token;active=health.active;await loadLocalRuns();}}catch{}}
 if(!runs.some(r=>r.id===selected))selected=runs.find(r=>r.status==='completed')?.id||runs[0]?.id||null;
 $('side-mode').textContent=local?'本机引擎服务':'真实算例展示';$('side-dot').classList.toggle('ready',local);$('connection-label').textContent=local?'本机服务已连接':'线上结果展示';$('mode-banner').querySelector('p').textContent=local?'已连接本机工作台。提交工况将调用官方 OpenFAST 程序，原始输入、日志和输出均保存在本机。':'当前为真实算例展示模式，可浏览、对比及导入结果。运行新工况请启动项目内的本机服务。';
 fillForm(current()?.params||draft);render();if(active)pollTimer=setTimeout(poll,1000);
 }catch(error){$('result-title').textContent='数据尚未就绪';$('insight-text').textContent=error.message;$('time-chart').innerHTML='<div class="empty">数据加载失败。请确认通过 HTTP 服务打开，且 samples.json 存在。</div>';$('connection-label').textContent='加载失败';toast(error.message,true);}}
init();

// Stable UI bridge: enhancements consume the same records and operations as the
// original workbench, never a second demo dataset or a second polling loop.
export function workspaceState(){return {runs:[...runs],record:current(),plots:plots(),comparison:[...comparison],local,active};}
export function workspaceSelect(id){selectRun(id);}
export function workspaceCompare(ids){comparison=new Set(ids.filter(id=>runs.some(r=>r.id===id&&r.status==='completed')).slice(0,4));render();persist();}
export function workspaceReport(){return reportHTML();}
